# Code generated by Claude
"""C1 check: does TASK_CFG's stance at its pedestal still reach the 12 task points with the given reach-map folders? (the left arm, any approach bin; a point counts when its cube
is reached in the shoulder frame at that stance)

    python experiments/c1_validate_stance.py data/reach_map_bench_new [data/reach_map_before_bench]
"""
import math
import sys

import numpy as np

from src.bench_stance import load_maps
from src.full_check import task_points
from src.stance_finder import robot_geometry
from src.task_beaker_hotplate import load_task
from src.task_config import TASK_CFG


def reached(maps, robot, arm, stance, q, P):
    """Bin numbers whose map reaches the world point P from the stance (x, y, yaw) at pedestal command q."""
    x, y, yaw = stance
    c, s = math.cos(yaw), math.sin(yaw)
    sx, sy, sz = robot["shoulder"][arm]
    dx, dy = P[0] - x, P[1] - y
    bx, by = c * dx + s * dy, -s * dx + c * dy                              # base frame
    r = np.array([bx - sx, by - sy, P[2] - (robot["base_z"] + robot["torso_z0"] + robot["lift_factor"] * q + sz)])
    out = []
    for (side, b), rm in maps.items():
        if side != arm:
            continue
        i = np.floor((r - rm.origin) / rm.cube).astype(int)
        if (i >= 0).all() and (i < rm.cubes.shape).all() and rm.cubes[tuple(i)]:
            out.append(b)
    return sorted(out)


if __name__ == "__main__":
    sim = load_task(cameras=False)
    model, data = sim.model, sim.data
    robot, pts = robot_geometry(model), task_points(model, data)
    stance = (*TASK_CFG["staging_xy"], TASK_CFG["staging_yaw"])
    for folder in sys.argv[1:]:
        maps = load_maps(folder)
        print(folder)
        n_ok = 0
        for pt in pts:
            bins = reached(maps, robot, "left", stance, TASK_CFG["pedestal_q"], pt["p"])
            n_ok += bool(bins)
            print(f"  {pt['path']:8s} {np.round(pt['p'], 3).tolist()}  bins {bins}")
        print(f"  {n_ok} of {len(pts)} reachable")
